987	  # c1 writes under t1 and is paused past its lifetime; c2 is granted t2 and READS
988	  # (served, highest_before = t1) but does not write. c1 resumes and writes with its
989	  # stale token while storage's replies to c1 are dropped (s->c1 down, c1->s up).
990	  # Storage must decide that write against a ledger still at t1: highest_before = t1,
991	  # so the write is accepted (C1.2's condition holds; C2.1 says serving a read does
992	  # not move the ledger). c1 is never told. Then c2 writes (ledger -> t2), the link
993	  # heals, c1's next stale write is rejected with highest_before = t2, and c2's final
994	  # read is served with c2's own value (C2.2). The end is the explicit ReadAck
995	  # because Rule E1's "quiescent" lists requests, writes and acks but not reads.
996	  - {at: start, do: {request: c1}}
997	  - {at: {event: Grant, client: c1}, do: {write: c1, value: v1}}
998	  - {at: {event: WriteAck, client: c1, outcome: accepted}, do: {cell: F1.3, pause: c1}}
999	  - {at: start, do: {request: c2}}
1000	  - {at: {event: Grant, client: c2}, do: {cell: F1.3, resume: c1}}
1001	  - {at: start, do: {read: c2}}
1002	  - {at: {event: ReadAck, client: c2, outcome: served}, do: {cell: F2.2, drop: [[s, c1]]}}
1003	  - {at: start, do: {write: c1, value: v2, token: stale}}
1004	  - {at: {event: WriteAccept}, do: {write: c2, value: v3}}
1005	  - {at: {event: WriteAck, client: c2, outcome: accepted}, do: {cell: F2.2, heal: true}}
1006	  - {at: start, do: {write: c1, value: v4, token: stale}}
1007	  - {at: {event: WriteAck, client: c1, outcome: rejected}, do: {read: c2}}
1008	end: {event: ReadAck, client: c2}
1009	bound: {events: 200}
