import json
import re
import sys


# ----------------------------------------------------------------------------------------------------------------
# A parser for the TLA+ values TLC prints.  derives: C3.5
# ----------------------------------------------------------------------------------------------------------------
class P:
    """derives: C3.5 -- recursive-descent parser over TLC's printed values"""
    TOK = re.compile(r'\s*(<<|>>|\|->|:>|@@|\\X|[\[\]{}(),]|"(?:[^"\\]|\\.)*"|-?\d+|TRUE|FALSE|[A-Za-z_][A-Za-z0-9_]*)')

    def __init__(self, s):
        self.toks = []
        pos = 0
        s = s.strip()
        while pos < len(s):
            m = self.TOK.match(s, pos)
            if not m:
                if s[pos:].strip() == '':
                    break
                raise ValueError(f'cannot tokenise at {s[pos:pos + 40]!r}')
            self.toks.append(m.group(1))
            pos = m.end()
        self.i = 0

    def peek(self):
        return self.toks[self.i] if self.i < len(self.toks) else None

    def take(self, t=None):
        x = self.toks[self.i]
        if t is not None and x != t:
            raise ValueError(f'expected {t} got {x}')
        self.i += 1
        return x

    def value(self):
        v = self.atom()
        if self.peek() == ':>':          # a function written d1 :> v1 @@ d2 :> v2
            self.take(':>')
            r = self.atom_full()
            f = {_key(v): r}
            while self.peek() == '@@':
                self.take('@@')
                k = self.atom()
                self.take(':>')
                f[_key(k)] = self.atom_full()
            return f
        return v

    def atom_full(self):
        return self.atom()

    def atom(self):
        t = self.peek()
        if t == '<<':
            self.take()
            out = []
            while self.peek() != '>>':
                out.append(self.value())
                if self.peek() == ',':
                    self.take()
            self.take('>>')
            return out
        if t == '{':
            self.take()
            out = []
            while self.peek() != '}':
                out.append(self.value())
                if self.peek() == ',':
                    self.take()
            self.take('}')
            return Set(out)
        if t == '[':
            self.take()
            out = {}
            while self.peek() != ']':
                k = self.take()
                self.take('|->')
                out[k] = self.value()
                if self.peek() == ',':
                    self.take()
            self.take(']')
            return out
        if t == '(':
            self.take()
            v = self.value()
            self.take(')')
            return v
        self.take()
        if t.startswith('"'):
            return json.loads(t)
        if t == 'TRUE':
            return True
        if t == 'FALSE':
            return False
        if re.fullmatch(r'-?\d+', t):
            return int(t)
        return t


class Set(list):
    """derives: C3.5 -- a TLA+ set (kept as a list, emitted sorted)"""


def _key(v):
    return v if not isinstance(v, list) else tuple(v)


def parse_trace(text):
    """derives: C3.5 -- the states of the (last) error trace in TLC output; returns (states, loop_index or None)"""
    lines = text.splitlines()
