            if ln.startswith('/\\ ') or (ln and not ln.startswith(' ') and cur and not ln.startswith('/\\')):
                if ln.startswith('/\\ '):
                    cur.append(ln[3:])
                else:
                    if cur is not None and cur:
                        states.append(cur)
                    cur = None
            elif ln.startswith(' ') and cur:
                cur[-1] += ' ' + ln.strip()
