# ----------------------------------------------------------------------------------------------------------------
def js(v, field=None):
    """derives: C3.5 -- JSON value: sets sorted, pairs as lists, sentinels as null"""
    if isinstance(v, Set):
        items = [js(x) for x in v]
        return sorted(items, key=lambda x: json.dumps(x, sort_keys=True))
    if isinstance(v, list):
        return [js(x) for x in v]
    if isinstance(v, dict):
        return {k: js(x, k) for k, x in v.items()}
