    # look-up tables for causes and refs
    grant_by_tok, agree_by, agreed_by, req_by, wa_by, ra_by, sdec_by = {}, {}, {}, {}, {}, {}, {}
    send_by, rreq_by, cc_dec, cc_at, refused_at, request_by = {}, {}, {}, {}, {}, {}

    def ident(p):
        i = inc.get(p, 0)
        s = seq.get((p, i), 0)
        seq[(p, i)] = s + 1
        return {'proc': p, 'inc': i, 'seq': s}

    def ref(r):
        return {'proc': r['proc'], 'inc': r['inc'], 'seq': r['seq']}

    def pkey(p):
        return json.dumps(js(p), sort_keys=True)

    for si, st in enumerate(states):
        for e in st['ev']:
            ev = e['event']
            p = e['proc']
            rec = ident(p)
            rec['event'] = ev
            causes = []
            if ev == 'Fault':
                rec['proc'] = 'env'
                for k in ('cell', 'crash', 'restart', 'pause', 'resume', 'clock', 'heal'):
                    if k in e:
                        rec[k] = e[k]
                if 'step' in e:
                    rec['step'] = step_num(e['step'])
                if 'partition' in e:
                    rec['partition'] = js(e['partition'])
                if 'links' in e:
                    rec['links'] = js(e['links'])
                if e.get('amnesia'):
                    rec['amnesia'] = True
                if 'restart' in e:
                    q = e['restart']
                    if e.get('amnesia') or q not in lease:
                        inc[q] = inc.get(q, 0) + 1
            elif ev == 'Request':
                rec.update(client=e['client'], key=e['key'])
                request_by[(e['client'], e['rid'])] = rec
            elif ev == 'Agree':
                rec.update(node=e['node'], incarnation=e['incarnation'], proposal=js(e['proposal']))
                agree_by[(e['node'], e['incarnation'], pkey(e['proposal']))] = rec
            elif ev == 'Agreed':
                rec.update(decider=e['decider'], node=e['node'], node_incarnation=e['node_incarnation'],
                           proposal=js(e['proposal']), counted_toward=sorted(js(e['counted_toward'])))
                a = agree_by.get((e['node'], e['node_incarnation'], pkey(e['proposal'])))
                if a:
                    causes.append(ref(a))
                agreed_by[(e['decider'], rec['inc'], e['node'], e['node_incarnation'], pkey(e['proposal']))] = rec
            elif ev == 'Grant':
                rec.update(client=e['client'], key=e['key'], token=e['token'], lifetime=e['lifetime'],
                           grantor_term=e['grantor_term'], config_epoch=e['config_epoch'])
                prop = {'client': e['client'], 'token': e['token'], 'lifetime': e['lifetime'],
                        'config_epoch': e['config_epoch'], 'term': e['grantor_term']}
                ins = e['inputs']
                inputs = []
                for q, qi in sorted(js(ins['agreed'])):
                    a = agreed_by.get((p, rec['inc'], q, qi, pkey(prop)))
                    item = {'name': 'agreed', 'value': q}
                    if a:
                        item['ref'] = ref(a)
                    inputs.append(item)
                inputs += [{'name': 'members', 'value': js(ins['members'])},
                           {'name': 'config_epoch', 'value': ins['config_epoch']},
                           {'name': 'grantor_term', 'value': ins['grantor_term']},
                           {'name': 'last_token', 'value': ins['last_token']}]
                g = grant_by_tok.get(ins['last_token'])
                if g:
                    inputs[-1]['ref'] = ref(g)
                rec['inputs'] = inputs
                rq = request_by.get((e['client'], e['rid']))
                if rq:
                    causes.append(ref(rq))
                grant_by_tok[e['token']] = rec
            elif ev in ('WriteAttempt', 'ReadAttempt'):
                rec.update(client=e['client'], key=e['key'], token=e['token'], grantor_term=e['grantor_term'])
                if ev == 'WriteAttempt':
                    rec['value'] = e['value']
                g = grant_by_tok.get(e['token'])
                if g:
                    causes.append(ref(g))
                (wa_by if ev == 'WriteAttempt' else ra_by)[e.get('wid', e.get('xid'))] = rec
            elif ev in ('WriteAccept', 'WriteReject', 'ReadAccept', 'ReadReject'):
                rec.update(key=e['key'], token=e['token'], highest_before=e['highest_before'],
                           grantor_term=e['grantor_term'])
                if ev == 'ReadAccept':
                    rec['value'] = js(e['value'])
                ins = e['inputs']
                rec['inputs'] = [{'name': 'token', 'value': ins['token']}, {'name': 'ledger', 'value': ins['ledger']},
                                 {'name': 'stored_value', 'value': js(ins['stored_value'])}]
                if 'value' in ins:
                    rec['inputs'].append({'name': 'value', 'value': js(ins['value'])})
                key = ('w', e['wid']) if 'wid' in e else ('r', e['xid'])
                att = (wa_by if key[0] == 'w' else ra_by).get(key[1])
                if att:
                    causes.append(ref(att))
                sdec_by[key] = rec
            elif ev in ('WriteAck', 'ReadAck'):
                rec.update(client=e['client'], key=e['key'], token=e['token'], outcome=e['outcome'],
                           grantor_term=e['grantor_term'])
                if ev == 'ReadAck' and e['outcome'] == 'served':
                    rec['value'] = js(e['value'])
                key = ('w', e['wid']) if 'wid' in e else ('r', e['xid'])
                d = sdec_by.get(key)
                if d:
                    causes.append(ref(d))
                att = (wa_by if key[0] == 'w' else ra_by).get(key[1])
                if att:
                    rec['answers'] = ref(att)
            elif ev == 'ReconfigSend':
                rec.update(operator=e['operator'], request_id=e['request_id'], to=e['to'],
                           members=js(e['members']))
                send_by[e['request_id']] = rec
            elif ev == 'ReconfigRequest':
                rec.update(operator=e['operator'], request_id=e['request_id'], members=js(e['members']))
                s = send_by.get(e['request_id'])
                if s:
                    causes.append(ref(s))
                rreq_by[(p, e['request_id'])] = rec
            elif ev == 'ReconfigRefused':
                rec.update(node=e['node'], request_id=e['request_id'], reason=e['reason'],
                           epoch=None if e['epoch'] == -1 else e['epoch'])
                ins = e['inputs']
                inputs = [{'name': 'request_id', 'value': ins['request_id']},
                          {'name': 'requested_members', 'value': js(ins['requested_members'])}]
                if 'pending' in ins:
                    item = {'name': 'pending', 'value': ins['pending']}
                    r0 = rreq_by.get((p, ins['pending']))
                    if r0:
                        item['ref'] = ref(r0)
                    inputs.append(item)
                if 'commit' in ins:
                    item = {'name': 'commit', 'value': ins['commit']}
                    c0 = cc_at.get((p, ins['commit'])) or cc_dec.get(ins['commit'])
                    if c0:
                        item['ref'] = ref(c0)
                    inputs.append(item)
                rec['inputs'] = inputs
                r0 = rreq_by.get((p, e['request_id']))
                if r0:
                    causes.append(ref(r0))
                refused_at[(p, e['request_id'])] = rec
            elif ev == 'ConfigCommitted':
                rec.update(node=e['node'], epoch=e['epoch'], members=js(e['members']),
                           request_id=js(e['request_id'], 'request_id'),
                           readmits=sorted(js(e['readmits'])), decided=e['decided'])
                if e['decided']:
                    ins = e['inputs']
                    prop = {'epoch': e['epoch'], 'members': e['members'], 'request_id': e['request_id']}
                    inputs = []
                    for q, qi in sorted(js(ins['agreed'])):
                        a = agreed_by.get((p, rec['inc'], q, qi, pkey(prop)))
                        item = {'name': 'agreed', 'value': q}
                        if a:
                            item['ref'] = ref(a)
                        inputs.append(item)
                    inputs += [{'name': 'old_members', 'value': js(ins['old_members'])},
                               {'name': 'old_epoch', 'value': ins['old_epoch']},
                               {'name': 'request_id', 'value': ins['request_id']},
                               {'name': 'requested_members', 'value': js(ins['requested_members'])}]
                    rec['inputs'] = inputs
                    cc_dec[e['epoch']] = rec
                    r0 = rreq_by.get((p, e['request_id']))
                    if r0:
                        causes.append(ref(r0))
                elif e['epoch'] > 0 and e['epoch'] in cc_dec:
                    causes.append(ref(cc_dec[e['epoch']]))
                cc_at[(p, e['epoch'])] = rec
            elif ev == 'ReconfigAck':
                rec.update(operator=e['operator'], request_id=e['request_id'], outcome=e['outcome'],
                           epoch=None if e['epoch'] == -1 else e['epoch'])
                fr = e['fr']
                src = refused_at.get((fr, e['request_id'])) if e['outcome'] != 'committed' else \
                    cc_at.get((fr, e['epoch']))
                if src:
                    causes.append(ref(src))
            else:
                for k, v in e.items():
                    if k not in ('event', 'proc'):
                        rec[k] = js(v)
            rec['causes'] = causes
            rec['run'] = run
            rec['side'] = 'model'
            rec['_state'] = si + 1
            out.append(rec)
    return out


def main(argv):
    if len(argv) < 3:
        print(__doc__, file=sys.stderr)
        return 2
    meta = {}
    if '--meta' in argv:
        k = argv.index('--meta')
        meta = json.load(open(argv[k + 1]))
        argv = argv[:k] + argv[k + 2:]
    text = open(argv[0]).read()
    states, loop = parse_trace(text)
    if not states:
        print('export: no trace in the TLC output', file=sys.stderr)
        return 1
    recs = export(states, argv[1], meta, loop)
    with open(argv[2], 'w') as f:
        for r in recs:
            r.pop('_state', None)
            f.write(json.dumps(r) + '\n')
    print(f'export: {len(states)} states, {len(recs)} records -> {argv[2]}' +
          (f' (lasso back to state {loop + 1})' if loop is not None else ''))
    return 0


if __name__ == '__main__':
    sys.exit(main(sys.argv[1:]))

